def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); st = list(feats.stratum); us = sorted(set(st))
    Z0 = np.column_stack([np.ones(n)] + [np.array([s == u for s in st], float) for u in us[1:]])
    R = np.corrcoef(X, rowvar=False); R = np.nan_to_num(R)

    def ll(cols):
        A = np.column_stack([Z0] + cols) if cols else Z0
        b = np.zeros(A.shape[1])
        for _ in range(30):
            eta = np.clip(A @ b, -30, 30); mu = 1 / (1 + np.exp(-eta)); w = mu * (1 - mu) + 1e-9
            H = A.T @ (A * w[:, None]) + 1e-6 * np.eye(A.shape[1])
            step = np.linalg.solve(H, A.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(A @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))

    def thr(a): return stats.chi2.isf(a, 1)
    gates = [0.05 / p, 0.02 / p, 0.02 / p, 0.01 / p]
    sel = []; base = ll([])
    while len(sel) < min(MAX_DRIVERS, len(gates)):
        cur = [X[:, j] for j in sel]; best, bj = -1, None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            g = 2 * (ll(cur + [X[:, j]]) - base)
            if g > best: best, bj = g, j
        if bj is None or best < thr(gates[len(sel)]): break
        # cluster swap: among near members with LL within 2, pick min sum of others' gains
        cl = [k for k in range(p) if abs(R[bj, k]) >= 0.6 and k not in sel]
        if len(cl) > 1:
            lls = {k: ll(cur + [X[:, k]]) for k in cl}; top = max(lls.values())
            cand = [k for k in cl if lls[k] >= top - 1.0]
            def sg(k): return sum(max(0, ll(cur + [X[:, k], X[:, m]]) - lls[k]) for m in cl if m != k)
            if len(cand) > 1: bj = min(cand, key=sg)
        sel.append(bj); base = ll([X[:, j] for j in sel])
    changed = True
    while changed and sel:
        changed = False; full = ll([X[:, j] for j in sel])
        for j in list(sel):
            if 2 * (full - ll([X[:, k] for k in sel if k != j])) < thr(0.02 / p):
                sel.remove(j); changed = True; break
    mains = [X[:, j] for j in sel]; m0 = ll(mains)
    mu0 = 1 / (1 + np.exp(-0.0)); r0 = y - y.mean()
    pairs = [(a, b) for a in range(p) for b in range(a, p)]
    P = np.column_stack([X[:, a] * X[:, b] for a, b in pairs]); P = (P - P.mean(0)) / (P.std(0) + 1e-9)
    sc = (P.T @ r0) ** 2 / (n * y.mean() * (1 - y.mean()))
    prods = []; alpha = 0.01 / len(pairs)
    for i in np.argsort(-sc)[:15]:
        a, b = pairs[i]
        cols = mains + [X[:, j] for j in (a, b) if j not in sel] + [X[:, a] * X[:, b] for a, b in prods]
        g = 2 * (ll(cols + [X[:, a] * X[:, b]]) - ll(cols))
        if g > thr(alpha) and all({a, b}.isdisjoint(q) for q in prods):
            prods.append((a, b)); alpha /= 5
        if len(prods) >= 2: break
    drivers = [ids[j] for j in sel]
    for a, b in prods:
        for j in (a, b):
            if ids[j] not in drivers: drivers.append(ids[j])
    drivers = drivers[:MAX_DRIVERS]
    cols = list(dict.fromkeys([ids[j] for j in sel] + [ids[j] for q in prods for j in q]))
    return Design(drivers=tuple(drivers), columns=tuple(cols),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

